function matchesEventType(type, pattern) {
  if (pattern === "*") return true;
  if (pattern === type) return true;
  if (pattern.endsWith(".*")) {
    const namespace = pattern.slice(0, -2);
    return type === namespace || type.startsWith(`${namespace}.`);
  }
  return false;
}

