class ChainedCache {
  #own = new Map();
  #parent;
  constructor(parent) { this.#parent = parent; }
  has(key) { return this.#own.has(key) || (this.#parent?.has(key) ?? false); }
  get(key) { return this.#own.has(key) ? this.#own.get(key) : this.#parent?.get(key); }
  set(key, value) { this.#own.set(key, value); }
}

const request = new ChainedCache();
const child = new ChainedCache(request);
