const graph = {
  errors: [],
  middleware: ["errors"],
  events: ["errors", "middleware"],
  cqrs: ["events"],
  http: ["middleware"],
  cache: ["errors"],
  testing: ["cqrs"],
};

function dependents(graph, target) {
  const found = new Set();
  let changed = true;
  while (changed) {
    changed = false;
    for (const [name, deps] of Object.entries(graph)) {
      if (!found.has(name) && deps.some((d) => d === target || found.has(d))) {
        found.add(name);
        changed = true;
      }
    }
  }
  return [...found].sort();
}

console.log(dependents(graph, "middleware").join(","));

