const adapter = (name, fails = false) => ({
  name,
  async start() {
    if (fails) throw new Error("port in use");
    console.log("start", name);
  },
  async stop() {
    console.log("stop", name);
  },
});

async function startOrRollback(adapters) {
  const started = [];
  try {
    for (const a of adapters) {
      await a.start();
      started.push(a);
    }
  } catch (error) {
    for (const a of started.reverse()) await a.stop();
    throw error;
  }
}

try {
  await startOrRollback([adapter("db"), adapter("cache"), adapter("http", true), adapter("metrics")]);
} catch (error) {
  console.log("failed:", error.message);
}

